  "edgeOrder": ["e2", "e1", "e3"],
  // Suggest to change order of nodes to represent flows better (if order from input does not)
  "nodeOrder": ["n2", "n1", "n3", "n4", "n5"],
  // Suggest to change layout direction, if it would improve readability
  "direction": "LR", 
